import re

with open('doc/superhero.md', 'r') as f:
    content = f.read()

# Find all paragraphs with ID references
id_pattern = r'(?:registry|id|identifier|reference).*?\s*(\d+)'

# Find paragraphs that mention a specific ID with height
id_height = {}
id_pub = {}

paragraphs = content.split('\n\n')

for para in paragraphs:
    ids = re.findall(r'(?:registry|id|identifier|reference).*?(\d+)', para, re.IGNORECASE)
    height = re.search(r'height.*?(\d+\.?\d*)\s*(?:cm|centimeters)', para, re.IGNORECASE)
    pub = re.search(r'publisher.*?(\d+)', para, re.IGNORECASE)

    for id_val in ids:
        if height:
            try:
                h = float(height.group(1))
                id_height[id_val] = h
            except:
                pass
        if pub:
            try:
                p = int(pub.group(1))
                id_pub[id_val] = p
            except:
                pass

print(f'Found {len(id_height)} entries with ID and height')
print(f'Found {len(id_pub)} entries with ID and publisher')

# Find common IDs
common_ids = set(id_height.keys()) & set(id_pub.keys())
print(f'Common IDs: {len(common_ids)}')

# Sample entries
for id_val in list(common_ids)[:5]:
    print(f'  ID {id_val}: height={id_height[id_val]}, publisher={id_pub[id_val]}')

